import { AuthMethod, InfisicalAuthError, LoginResponse } from "./types";

export interface OidcAuthInput {
    baseUrl: string;
    identityId: string;
    jwt: string;
    timeoutMs?: number;
}

export async function loginWithOidc(input: OidcAuthInput): Promise<LoginResponse> {
    const url = new URL("/api/v1/auth/oidc-auth/login", input.baseUrl).toString();
    const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ identityId: input.identityId, jwt: input.jwt }),
        signal: AbortSignal.timeout(input.timeoutMs ?? 15000),
    });
    if (!response.ok) {
        throw new InfisicalAuthError(response.status, await response.text(), AuthMethod.Oidc);
    }
    return (await response.json()) as LoginResponse;
}

export enum AuthMethod {
    UniversalAuth = "universal-auth",
    Oidc = "oidc",
}

export type LoginRequest =
    | { method: AuthMethod.UniversalAuth; baseUrl: string; clientId: string; clientSecret: string }
    | { method: AuthMethod.Oidc; baseUrl: string; identityId: string; jwt: string };

export interface LoginResponse {
    accessToken: string;
    expiresIn: number;
    accessTokenMaxTTL: number;
    tokenType: "Bearer";
}

export class InfisicalAuthError extends Error {
    constructor(
        public readonly status: number,
        public readonly body: string,
        public readonly endpoint: string,
    ) {
        super(`Infisical ${endpoint} login failed with status ${status}: ${body}`);
        this.name = "InfisicalAuthError";
    }
}

import { AuthMethod, InfisicalAuthError, LoginResponse } from "./types";

export interface UniversalAuthInput {
    baseUrl: string;
    clientId: string;
    clientSecret: string;
    timeoutMs?: number;
}

export async function loginWithUniversalAuth(input: UniversalAuthInput): Promise<LoginResponse> {
    const url = new URL("/api/v1/auth/universal-auth/login", input.baseUrl).toString();
    const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ clientId: input.clientId, clientSecret: [REDACTED] }),
        signal: AbortSignal.timeout(input.timeoutMs ?? 15000),
    });
    if (!response.ok) {
        throw new InfisicalAuthError(response.status, await response.text(), AuthMethod.UniversalAuth);
    }
    return (await response.json()) as LoginResponse;
}

export interface AzureOidcTokenInput {
    oidcRequestUri: string;
    adoAccessToken: string;
    serviceConnectionId: string;
    timeoutMs?: number;
}

export class AzureOidcTokenError extends Error {
    constructor(
        public readonly status: number,
        public readonly body: string,
    ) {
        super(`Azure OIDC token request failed with status ${status}: ${body}`);
        this.name = "AzureOidcTokenError";
    }
}

export async function fetchAzureOidcToken(input: AzureOidcTokenInput): Promise<string> {
    const url = new URL(input.oidcRequestUri);
    url.searchParams.set("api-version", "7.1-preview.1");
    url.searchParams.set("serviceConnectionId", input.serviceConnectionId);

    const response = await fetch(url.toString(), {
        method: "POST",
        headers: {
            Authorization: `Bearer ${input.adoAccessToken}`,
            Accept: "application/json",
            "Content-Length": "0",
        },
        signal: AbortSignal.timeout(input.timeoutMs ?? 15000),
    });
    if (!response.ok) {
        throw new AzureOidcTokenError(response.status, await response.text());
    }
    const body = (await response.json()) as { oidcToken?: string };
    if (!body.oidcToken) {
        throw new AzureOidcTokenError(response.status, "response missing oidcToken");
    }
    return body.oidcToken;
}

import { AuthMethod, LoginRequest, LoginResponse } from "./types";
import { loginWithUniversalAuth } from "./universalAuth";
import { loginWithOidc } from "./oidc";

export async function login(request: LoginRequest): Promise<LoginResponse> {
    switch (request.method) {
        case AuthMethod.UniversalAuth:
            return loginWithUniversalAuth({
                baseUrl: request.baseUrl,
                clientId: request.clientId,
                clientSecret: [REDACTED],
            });
        case AuthMethod.Oidc:
            return loginWithOidc({
                baseUrl: request.baseUrl,
                identityId: request.identityId,
                jwt: request.jwt,
            });
        default: {
            const exhaustive: never = request;
            throw new Error(
                `Unsupported Infisical auth method: ${(exhaustive as { method: string }).method}`,
            );
        }
    }
}

